// Healed 2026-11-03 by autotest-writer (not run): «פרופיל גלוי» step removed (#daf026), fixed phone → uniquePhone().
import { test, expect } from '@playwright/test';
import path from 'path';
import { openAddCandidate, fillStep1, closeAddCandidate, searchMyCandidates, stamp, uniquePhone } from './helpers';

test.use({ storageState: path.join(__dirname, '../../../auth/hunter_plus.json') });

const ts = stamp();
const FIRST = 'QA-AUTO 7818c8';

test.describe('«הוספת מועמד» — save only on «סיום» (#7818c8)', () => {
  test.afterAll(async ({ browser }) => {
    // Cleanup: the candidate must not exist; if it does (regression) — the UI has no delete, log it for manual cleanup.
    const page = await browser.newPage({ storageState: path.join(__dirname, '../../../auth/hunter_plus.json') });
    const found = await (await searchMyCandidates(page, ts)).filter({ hasText: `${FIRST} ${ts}` }).count();
    if (found) console.warn(`[test-data] leftover candidate «${FIRST} ${ts}» — delete manually`);
    await page.close();
  });

  test('Closing on step 2 asks to confirm and does not create the candidate @desktop @data #7818c8', async ({ page }) => {
    // 1. Step 1 (no profile-type choice since #daf026; unique phone — a repeated one is rejected) → «המשך»
    const dialog = await openAddCandidate(page);
    await fillStep1(dialog, {
      first: FIRST, last: ts, phone: uniquePhone(),
      about: 'QA-AUTO מועמד לבדיקה', field: 'שיווק, מכירות ופיתוח עסקי',
    });
    const title = dialog.getByRole('textbox', { name: 'כותרת' });
    await expect(title).toBeVisible();
    await expect(title).not.toHaveValue('', { timeout: 60_000 });
    const titleValue = await title.inputValue();

    // 2. «סגירה» → confirm dialog → «המשך עריכה»
    await dialog.getByRole('button', { name: 'סגירה' }).click();
    const confirm = page.getByRole('dialog', { name: 'לצאת בלי לשמור?' });
    await expect(confirm).toBeVisible();
    await expect(confirm.getByText('המועמד לא יישמר. מה שמילאתם עד עכשיו יימחק')).toBeVisible();
    await expect(confirm.getByRole('button', { name: 'יציאה', exact: true })).toBeVisible();
    await confirm.getByRole('button', { name: 'המשך עריכה', exact: true }).click();
    await expect(confirm).toBeHidden();
    // Step 2 still open with the data
    await expect(title).toHaveValue(titleValue);
    await expect(dialog.getByRole('button', { name: 'סיום', exact: true })).toBeVisible();

    // 3. «סגירה» → «יציאה»
    await closeAddCandidate(page, 'יציאה');
    await expect(dialog).toBeHidden();

    // 4. «המועמדים שלי» — no «QA-AUTO 7818c8 <ts>»
    const headings = await searchMyCandidates(page, ts);
    await expect(headings.filter({ hasText: `${FIRST} ${ts}` })).toHaveCount(0);
  });
});
